import { z } from 'zod';

export const startConversationInput = z.object({
  listingId: z.uuid(),
  body: z.string().trim().min(1).max(4000).optional(),
});

export const sendMessageInput = z.object({
  body: z.string().trim().min(1, "can't send an empty message").max(4000),
  // generated by the client; resending the same clientId is a no-op
  clientId: z.uuid(),
});
export type SendMessageInput = z.infer<typeof sendMessageInput>;

export const messageHistoryQuery = z.object({
  // older than this seq (scrolling up), or newer than it (catching up)
  before: z.coerce.number().int().positive().optional(),
  after: z.coerce.number().int().min(0).optional(),
  limit: z.coerce.number().int().min(1).max(100).default(50),
});

export const markReadInput = z.object({ seq: z.number().int().min(0) });

export interface Message {
  id: string;
  conversationId: string;
  seq: number;
  senderId: string;
  body: string;
  clientId: string;
  createdAt: string;
}

export interface ConversationSummary {
  id: string;
  listing: { id: string; title: string; city: string; coverUrl: string | null };
  other: { id: string; displayName: string };
  lastMessage: Pick<Message, 'body' | 'senderId' | 'createdAt' | 'seq'> | null;
  lastSeq: number;
  unread: number;
  // how far the *other* person has got, for "delivered" / "seen" ticks
  otherDeliveredSeq: number;
  otherReadSeq: number;
  lastMessageAt: string | null;
}

// --- socket events --------------------------------------------------------
// Delivery over the socket is best effort and may repeat or arrive out of
// order. Clients key messages by id, sort by seq, and if they see a gap they
// fetch ?after=<last seq they have>.

export interface ServerToClientEvents {
  'message:new': (m: Message) => void;
  'receipt': (r: { conversationId: string; userId: string; deliveredSeq: number; readSeq: number }) => void;
  'typing': (t: { conversationId: string; userId: string; typing: boolean }) => void;
  'presence': (p: { userId: string; online: boolean }) => void;
  'notification': (n: { id: string; type: string; payload: Record<string, unknown>; createdAt: string }) => void;
  'booking:updated': (b: { id: string; status: string; listingId: string }) => void;
  'unread': (u: { messages: number; notifications: number }) => void;
}

export interface ClientToServerEvents {
  'typing': (t: { conversationId: string; typing: boolean }) => void;
  'delivered': (d: { conversationId: string; seq: number }) => void;
  'presence:watch': (userIds: string[], cb: (online: Record<string, boolean>) => void) => void;
}
